import fs from'node:fs';import crypto from'node:crypto';import path from'node:path';
const mode=process.argv[2],root='/workspace/.eliza/client-features',hash=b=>crypto.createHash('sha256').update(b).digest('hex');
if(mode==='before'){if(fs.existsSync('/workspace/.eliza'))throw Error('Borrowed generated producer output');process.exit(0);}
if(!['after','final'].includes(mode))throw Error('Unknown custody mode');
const stamp=JSON.parse(fs.readFileSync(root+'/.source.json'));if(stamp.baseCommit!=='ff04a558747ed426d9d871a319f7b3946f7660e6'||stamp.projectionVersion!==12)throw Error('Wrong normal producer subject');
const observed={},records=[];let bytes=0;function walk(dir){for(const e of fs.readdirSync(dir,{withFileTypes:true})){const f=path.join(dir,e.name),r=path.relative(root,f);if(e.isSymbolicLink())throw Error('Borrowed output');if(e.isDirectory())walk(f);else{if(!e.isFile())throw Error('Special output');const b=fs.readFileSync(f);bytes+=b.length;if(bytes>536870912||records.length>10000)throw Error('Output bounds');if(r!=='.source.json')observed[r]=hash(b);records.push({path:r,sha256:hash(b),bytes:b.length});}}}walk(root);const sort=x=>JSON.stringify(Object.entries(x).sort());if(sort(observed)!==sort(stamp.files))throw Error('Producer output/normalreceipt mismatch');
const result={baseCommit:stamp.baseCommit,projectionVersion:stamp.projectionVersion,files:records.sort((a,b)=>a.path<b.path?-1:1),bytes,stampSHA256:hash(fs.readFileSync(root+'/.source.json'))};if(mode==='final'&&JSON.stringify(result)!==fs.readFileSync('/results/PROJECTION-after.json','utf8').trim())throw Error('Producer output changed during tests');fs.writeFileSync('/results/PROJECTION-'+mode+'.json',JSON.stringify(result)+'\n');
